use std::fmt::Write as _;
use std::path::PathBuf;

/// `packaging/windows/mellow.ico`, generated by `cargo xtask tokens` from the favicon.
const WINDOWS_ICON: &str = "packaging/windows/mellow.ico";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let target_os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    // ScreenCaptureKit exists from macOS 12.3 while the app starts from 11.0 (ADR-0055):
    // weak-linking it lets dyld start the app without it, and screen sharing then reports itself
    // unavailable (mellow-media checks for `SCStream` at run time). The binary imports no
    // ScreenCaptureKit symbol.
    if target_os == "macos" {
        println!("cargo:rustc-link-arg-bins=-Wl,-weak_framework,ScreenCaptureKit");
    }
    // GPUI links its manifest (DPI awareness, no elevation) into every binary using it; the app
    // adds its icon (resource 1, which GPUI's windows load) and version information (ADR-0060).
    if target_os == "windows" {
        embed_windows_resources()?;
    }
    Ok(())
}

fn embed_windows_resources() -> Result<(), Box<dyn std::error::Error>> {
    let manifest_directory =
        PathBuf::from(std::env::var_os("CARGO_MANIFEST_DIR").unwrap_or_else(|| ".".into()));
    let output_directory = PathBuf::from(std::env::var_os("OUT_DIR").unwrap_or_else(|| ".".into()));
    println!("cargo:rerun-if-changed={WINDOWS_ICON}");
    let quoted = |relative: &str| {
        manifest_directory
            .join(relative)
            .display()
            .to_string()
            .replace('\\', "\\\\")
    };
    let version = std::env::var("CARGO_PKG_VERSION").unwrap_or_default();
    let numeric_version = ["MAJOR", "MINOR", "PATCH"]
        .map(|part| std::env::var(format!("CARGO_PKG_VERSION_{part}")).unwrap_or_default())
        .join(",");
    let mut script = String::new();
    // Resource id 1: the icon GPUI loads. No manifest: GPUI's is already linked in.
    let _ = writeln!(script, "1 ICON \"{}\"", quoted(WINDOWS_ICON));
    let _ = write!(
        script,
        r#"1 VERSIONINFO
FILEVERSION {numeric_version},0
PRODUCTVERSION {numeric_version},0
FILEOS 0x40004
FILETYPE 0x1
BEGIN
  BLOCK "StringFileInfo"
  BEGIN
    BLOCK "040904B0"
    BEGIN
      VALUE "CompanyName", "Mellow"
      VALUE "FileDescription", "Mellow"
      VALUE "FileVersion", "{version}"
      VALUE "InternalName", "mellow"
      VALUE "LegalCopyright", "AGPL-3.0-or-later"
      VALUE "OriginalFilename", "mellow.exe"
      VALUE "ProductName", "Mellow"
      VALUE "ProductVersion", "{version}"
    END
  END
  BLOCK "VarFileInfo"
  BEGIN
    VALUE "Translation", 0x409, 1200
  END
END
"#
    );
    let script_path = output_directory.join("mellow.rc");
    std::fs::write(&script_path, script)?;
    embed_resource::compile(&script_path, embed_resource::NONE)
        .manifest_required()
        .map_err(|error| format!("cannot embed the Windows resources: {error}"))?;
    Ok(())
}
